#!/usr/bin/env python3
# native_group_probes.py — b442 (2026-08-28)
#
# The native operation-history no-go at b76B depth one.
#
# b441 left one question live in neither direction: the native relations bind a conservative lift
# P_o (x) U_o only PROJECTIVELY, and the invariant that would decide whether any such lift carries
# gauge-invariant structure is the class of a 2-cocycle in H^2(G, U(1)), where G is the group
# generated by the native operations. b441 did not compute it. This file does, and the answer
# arrives in two parts, neither of which is the cocycle computation b441 anticipated.
#
# PART ONE: G IS NOT NATIVE DATA. The native evolution phi is a PARTIAL map. The b76B realization
# extends it to a bijection by matching the two complements in sorted order -- 512 of the 576
# states are assigned an image by that completion and not by the dynamics. Different completions of
# the SAME genuine dynamics give phi different orders, so the marked group <phi, I_0, I_1> and every
# invariant of it, H^2 included, is a property of an arbitrary choice. NG2 exhibits the variation.
#
# PART TWO: THE GENUINE LOOPS CARRY NO COCYCLE. On the genuine transition relation the evolution
# has DEPTH ONE: phi's genuine domain is the c = 0 slice and its genuine image is the c = 1 slice,
# these are disjoint, and both instruments are the identity on c = 1. So nothing genuine ever
# returns from where phi lands, and NO GENUINE CLOSED LOOP CONTAINS phi -- proved structurally in
# NG4 and confirmed by exhaustive enumeration. Every genuine closed loop therefore lies in the
# instrument group <I_0, I_1>, which is padding-independent of order 6. Its Schur multiplier is
# computed exactly here, from a normalized bar resolution over Z with Smith normal form, and is
# TRIVIAL; since U(1) is divisible, H^2(-, U(1)) vanishes with it.
#
# The two parts together close the operation-history route FOR b76B AS PRESENTLY CONSTRUCTED. They
# do not close it for OI. The distinction is the whole point of NG7: depth one is not a parameter
# somebody set to 1, it is compiled into the construction -- the kernel table is built from
# length-1 contexts only, so the c = 1 lookup a K >= 2 run would perform has no entry at all. A
# meaningful test beyond this no-go needs a genuine variable-context K >= 2 realization, in which
# successive native phi steps and genuine dynamical loops can exist without padding a partial map.
#
# FOUR STRUCTURES, KEPT APART, exactly as b441 kept its two conservativities apart:
#     operation-history cocycle  =/=  Berry/Bargmann section  =/=  local spatial curvature
#                                =/=  the U(1)_Y identification.
# This file attacks ONLY the first. A trivial multiplier here says nothing about the other three,
# and H-observer-bundle and H-Y-vertex remain exactly as open as b441 left them.
#
#   NG1  the native construction, and the genuine / padded split of phi
#   NG2  the marked group is an artifact: ord(phi) varies with the completion
#   NG3  depth one -- phi's genuine domain and image are disjoint slices
#   NG4  no genuine closed loop contains phi; the loops are the instrument group
#   NG5  that group is padding-independent, order 6, nonabelian
#   NG6  its integer homology, from scratch, with a NONTRIVIAL positive control
#   NG7  K >= 2 is not available in b76B: depth one is a construction boundary
#   NG8  the two-part no-go, gated on every control above
#
# Usage:  python3 native_group_probes.py

import itertools, sys
from fractions import Fraction as F
from math import lcm

CHECKS = []

def check(label, ok, msg):
    CHECKS.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {label}: {msg}", flush=True)

def verdict(label, ok, msg):
    """A TERMINAL SUMMARY: it has no computation of its own, it only states what the checks above
    have established. Gating the label is not enough -- check() prints its msg whatever the label
    says, so a bare gate renders the entire verdict text under a FAIL heading, which is the thing
    the gate exists to prevent. The message itself is therefore withheld when a control has failed."""
    check(label, ok, msg if ok else
          "WITHHELD — a prerequisite control above failed, so this summary is not asserted")

# ---------------------------------------------------------------- the native construction (b76B)
# Lifted verbatim from coherence_boundary_probes.py, with ONE change that is the point of the round:
# the genuine part of phi and the arbitrary bijective completion are kept as separate objects
# instead of being merged by the zip. Nothing else differs, and NG1 checks that the merged result
# still reproduces the b76B numbers.
nV, nA, BLANK, K = 2, 2, -1, 1

def kern(ctx):
    xs, as_ = ctx
    p = F((1 + sum(xs) + 2 * sum(as_) + 3 * len(xs) + (xs[-1] ^ as_[-1])) % 7 + 1, 9)
    return {0: 1 - p, 1: p}

CTXS = [((x,), (a,)) for x in range(nV) for a in range(nA)]
tabs = [{}]
for c in CTXS:
    nxt = []
    for tb in tabs:
        for y in range(nV):
            if kern(c)[y] > 0:
                t2 = dict(tb); t2[c] = y; nxt.append(t2)
    tabs = nxt
UTAB = [tuple(sorted(tb.items())) for tb in tabs]
XH = list(itertools.product(list(range(nV)) + [BLANK], repeat=K))
AH = list(itertools.product(list(range(nA)) + [BLANK], repeat=K))
STATES = [(x, h, a, u, c) for x in range(nV) for h in XH for a in AH
          for u in range(len(UTAB)) for c in range(K + 1)]

def wf_x(h, c): return all(h[i] != BLANK for i in range(c)) and all(h[i] == BLANK for i in range(c, K))

def wf_a(a, c, wrote):
    m = c + (1 if wrote else 0)
    return all(a[i] != BLANK for i in range(m)) and all(a[i] == BLANK for i in range(m, K))

def instrument(act):
    d = {}
    for s in STATES:
        x, h, a, u, c = s
        if c < K:
            al = list(a)
            if al[c] == BLANK: al[c] = act
            elif al[c] == act: al[c] = BLANK
            d[s] = (x, h, tuple(al), u, c)
        else:
            d[s] = s
    return d

INSTR = {act: instrument(act) for act in range(nA)}

PHI_GENUINE = {}
for s in STATES:
    x, h, a, u, c = s
    if c < K and wf_x(h, c) and wf_a(a, c, wrote=True):
        ctx = (tuple(list(h[:c]) + [x]), tuple(a[:c + 1]))
        PHI_GENUINE[s] = (dict(UTAB[u])[ctx], tuple(list(h[:c]) + [x] + [BLANK] * (K - c - 1)),
                          a, u, c + 1)
UND = sorted(set(STATES) - set(PHI_GENUINE))            # states the dynamics gives no image
UNH = sorted(set(STATES) - set(PHI_GENUINE.values()))   # states the dynamics reaches from nowhere

def phi_completed(match):
    """The genuine dynamics extended to a bijection by the matching UND[i] -> UNH[match[i]]."""
    d = dict(PHI_GENUINE)
    for i, j in enumerate(match):
        d[UND[i]] = UNH[j]
    return d

PHI_REPO = phi_completed(list(range(len(UND))))          # b76B's sorted-order zip

IDX = {s: i for i, s in enumerate(STATES)}
def perm(d): return tuple(IDX[d[s]] for s in STATES)
def compose(p, q): return tuple(p[q[i]] for i in range(len(q)))
ID = tuple(range(len(STATES)))

def order(pm):
    """Order via cycle type. Iterating to the identity is the same number and takes minutes here."""
    n = len(pm); seen = [False] * n; o = 1
    for i in range(n):
        if not seen[i]:
            L = 0; j = i
            while not seen[j]: seen[j] = True; j = pm[j]; L += 1
            o = lcm(o, L)
    return o

# ---------------------------------------------------------------- NG1  the genuine / padded split
ok1 = (len(STATES) == 576 and len(UTAB) == 16 and len(UND) == len(UNH))
ok1 &= (sorted(PHI_REPO.values()) == sorted(STATES))
ok1 &= all(sorted(m.values()) == sorted(STATES) for m in INSTR.values())
GENUINE, PADDED = len(PHI_GENUINE), len(UND)
ok1 &= (GENUINE == 64 and PADDED == 512 and GENUINE + PADDED == len(STATES))
check("NG1", ok1,
      f"the b76B realization reproduces: {len(STATES)} states, {len(UTAB)} kernel tables, and the "
      f"completed phi and both instruments are bijections. But phi is GENUINE on only {GENUINE} of "
      f"{len(STATES)} states ({GENUINE / len(STATES):.1%}): the dynamics assigns an image exactly "
      f"where c < K and the histories are well formed, and the remaining {PADDED} states are given "
      f"images by MATCHING THE TWO COMPLEMENTS IN SORTED ORDER. That matching is a choice made to "
      f"obtain a permutation, not a fact about the model")

# ---------------------------------------------------------------- NG2  the marked group is an artifact
# A deterministic spread of completions, not a random sample: each is an explicit permutation of the
# complement, so the comparison is reproducible and does not depend on a seed.
def rotate(k): return [(i + k) % len(UND) for i in range(len(UND))]
def stride(k): return sorted(range(len(UND)), key=lambda i: (i * k) % len(UND))
ALT = {'sorted zip (b76B)': list(range(len(UND))), 'rotate 1': rotate(1), 'rotate 7': rotate(7),
       'reverse': list(reversed(range(len(UND)))), 'stride 3': stride(3), 'stride 5': stride(5)}
ORDS = {name: order(perm(phi_completed(m))) for name, m in ALT.items()}
REPO_ORD = ORDS['sorted zip (b76B)']
ok2 = (len(set(ORDS.values())) > 1)
# and the genuine part is the SAME map in every one of them, so the variation is purely the padding
ok2 &= all(phi_completed(m)[s] == PHI_GENUINE[s] for m in ALT.values() for s in PHI_GENUINE)
check("NG2", ok2,
      f"the completion is not a harmless bookkeeping step: over {len(ALT)} explicit completions of "
      f"the IDENTICAL genuine dynamics, ord(phi) takes {len(set(ORDS.values()))} distinct values "
      f"({', '.join(str(v) for v in sorted(set(ORDS.values())))}), b76B's own being {REPO_ORD}. "
      f"Every completion restricts to the same map on all {GENUINE} genuine states, so the spread "
      f"is entirely the padding. THE MARKED GROUP <phi, I_0, I_1> IS THEREFORE NOT NATIVE DATA, and "
      f"neither is any invariant of it — H^2(G, U(1)) included. This is why the round does not "
      f"compute |G|: the number would be a property of the sorted() call, not of OI")

# ---------------------------------------------------------------- NG3  depth one
DOM_C = {s[4] for s in PHI_GENUINE}
IMG_C = {t[4] for t in PHI_GENUINE.values()}
FROZEN = [s for s in STATES if s[4] == K]
ok3 = (DOM_C == {0} and IMG_C == {K} and K == 1)
ok3 &= (set(PHI_GENUINE) & set(PHI_GENUINE.values()) == set())          # domain and image disjoint
ok3 &= (len([s for s in PHI_GENUINE if PHI_GENUINE[s] in PHI_GENUINE]) == 0)   # phi o phi: nowhere
ok3 &= all(INSTR[a][s] == s for a in range(nA) for s in FROZEN)          # instruments frozen there
ok3 &= all(t in FROZEN for t in PHI_GENUINE.values())
check("NG3", ok3,
      f"THE GENUINE EVOLUTION HAS DEPTH ONE. phi's genuine domain is exactly the c = 0 slice and "
      f"its genuine image is exactly the c = {K} slice; the two are DISJOINT, so phi o phi is "
      f"genuinely defined on 0 states. Both instruments are verified to be the identity on all "
      f"{len(FROZEN)} states with c = {K}, which is precisely where phi lands. So no genuine "
      f"operation of any kind acts after the single phi step")

# ---------------------------------------------------------------- NG4  no genuine loop contains phi
# Two independent arguments, because this is the load-bearing claim of the round.
# (a) STRUCTURAL. Genuine steps never decrease c and phi strictly increases it, so a word containing
#     phi cannot return to its start. The two premises are checked directly rather than asserted.
GEN = {'phi': PHI_GENUINE,
       'I_0': {s: INSTR[0][s] for s in STATES if s[4] < K},
       'I_1': {s: INSTR[1][s] for s in STATES if s[4] < K}}
NEVER_DECREASES = all(m[s][4] >= s[4] for m in GEN.values() for s in m)
PHI_INCREASES = all(PHI_GENUINE[s][4] > s[4] for s in PHI_GENUINE)
ok4 = NEVER_DECREASES and PHI_INCREASES
# (b) EXHAUSTIVE. Every genuine word up to MAXLEN from every one of the 576 states.
MAXLEN = 8
CLOSED = set()
for s0 in STATES:
    stack = [(s0, ())]
    while stack:
        cur, w = stack.pop()
        if w and cur == s0:
            CLOSED.add(w); continue
        if len(w) >= MAXLEN: continue
        for name, m in GEN.items():
            if cur in m: stack.append((m[cur], w + (name,)))
ok4 &= (len(CLOSED) > 0)
ok4 &= all('phi' not in w for w in CLOSED)
INSTRUMENT_ONLY = all(set(w) <= {'I_0', 'I_1'} for w in CLOSED)
ok4 &= INSTRUMENT_ONLY
check("NG4", ok4,
      f"NO GENUINE CLOSED OPERATIONAL LOOP CONTAINS phi, by two independent arguments. "
      f"STRUCTURALLY: every genuine step is verified never to decrease the counter c and phi is "
      f"verified to strictly increase it, so a word containing phi cannot return to its start. "
      f"EXHAUSTIVELY: over all {len(STATES)} start states and every genuine word up to length "
      f"{MAXLEN}, {len(CLOSED)} distinct closed words exist and NOT ONE of them contains phi — "
      f"every closed word lies in {{I_0, I_1}}. The holonomy of a conservative lift around a "
      f"genuine loop is therefore a datum of the INSTRUMENT group alone, and the dynamics "
      f"contributes no loop for a phase to accumulate over")

# ---------------------------------------------------------------- NG5  the instrument group
def generated(gens):
    seen = {ID}; frontier = [ID]
    while frontier:
        nf = []
        for q in frontier:
            for g in gens:
                r = compose(g, q)
                if r not in seen: seen.add(r); nf.append(r)
        frontier = nf
    return seen

I0, I1 = perm(INSTR[0]), perm(INSTR[1])
GRP = sorted(generated([I0, I1]))
NONABELIAN = compose(I0, I1) != compose(I1, I0)
ok5 = (len(GRP) == 6 and NONABELIAN)
ok5 &= (order(I0) == 2 and order(I1) == 2 and order(compose(I0, I1)) == 3)
# padding-independence is structural: phi appears nowhere in the construction of this group
ok5 &= all(g in GRP for g in (I0, I1)) and ID in GRP
check("NG5", ok5,
      f"the genuine loops live in <I_0, I_1>, which has order {len(GRP)} and is NONABELIAN, with "
      f"both generators of order 2 and their product of order 3 — b441's relation, recovered here "
      f"as the group's defining structure rather than as one tested word. phi enters its "
      f"construction nowhere, so unlike <phi, I_0, I_1> this group is PADDING-INDEPENDENT: it is "
      f"the same group under every completion in NG2, and it is genuine native data")

# ---------------------------------------------------------------- NG6  its Schur multiplier, exactly
# H_n(G, Z) from the NORMALIZED BAR RESOLUTION, in exact integer arithmetic, with no cited value and
# no library. C_n is free on n-tuples of non-identity elements; a cell acquiring an identity entry
# is zero. H_n = ker d_n / im d_(n+1), read off by Smith normal form.
def kernel_basis(A, n):
    """Integer kernel of an m x n matrix by unimodular COLUMN reduction. The kernel of an integer
    matrix is saturated, so the result is a direct summand and coordinates in it are integral."""
    A = [row[:] for row in A]; m = len(A)
    V = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    def colop(j, k, q):
        for i in range(m): A[i][j] -= q * A[i][k]
        for i in range(n): V[i][j] -= q * V[i][k]
    def colswap(j, k):
        for i in range(m): A[i][j], A[i][k] = A[i][k], A[i][j]
        for i in range(n): V[i][j], V[i][k] = V[i][k], V[i][j]
    piv = 0
    for r in range(m):
        while True:
            nz = [j for j in range(piv, n) if A[r][j] != 0]
            if not nz: break
            colswap(piv, min(nz, key=lambda j: abs(A[r][j])))
            for j in range(piv + 1, n):
                if A[r][j] != 0: colop(j, piv, A[r][j] // A[r][piv])
            if all(A[r][j] == 0 for j in range(piv + 1, n)): break
        if any(A[r][j] != 0 for j in range(piv, n)): piv += 1
        if piv == n: break
    return [[V[i][j] for i in range(n)] for j in range(n) if all(A[i][j] == 0 for i in range(m))]

def smith_invariants(M, m, n):
    A = [row[:] for row in M]; inv = []; t = 0
    def pivot(t):
        p = None
        for i in range(t, m):
            for j in range(t, n):
                if A[i][j] != 0 and (p is None or abs(A[i][j]) < abs(A[p[0]][p[1]])): p = (i, j)
        return p
    while t < m and t < n:
        p = pivot(t)
        if p is None: break
        while True:
            A[t], A[p[0]] = A[p[0]], A[t]
            for i in range(m): A[i][t], A[i][p[1]] = A[i][p[1]], A[i][t]
            for i in range(t + 1, m):
                if A[i][t]:
                    q = A[i][t] // A[t][t]
                    for j in range(t, n): A[i][j] -= q * A[t][j]
            for j in range(t + 1, n):
                if A[t][j]:
                    q = A[t][j] // A[t][t]
                    for i in range(t, m): A[i][j] -= q * A[i][t]
            if (all(A[i][t] == 0 for i in range(t + 1, m))
                    and all(A[t][j] == 0 for j in range(t + 1, n))): break
            p = pivot(t)
        inv.append(abs(A[t][t])); t += 1
    return inv

def solve_exact(B, v):
    """The unique rational solution of B x = v for B of full column rank, or None."""
    r = len(B[0]) if B and B[0] else 0
    M = [[Fraction(B[i][j]) for j in range(r)] + [Fraction(v[i])] for i in range(len(B))]
    row = 0; where = [-1] * r
    for col in range(r):
        p = next((i for i in range(row, len(M)) if M[i][col] != 0), None)
        if p is None: continue
        M[row], M[p] = M[p], M[row]
        pv = M[row][col]; M[row] = [x / pv for x in M[row]]
        for i in range(len(M)):
            if i != row and M[i][col] != 0:
                f = M[i][col]; M[i] = [a - f * b for a, b in zip(M[i], M[row])]
        where[col] = row; row += 1
    x = [M[where[j]][r] if where[j] >= 0 else Fraction(0) for j in range(r)]
    for i in range(len(M)):
        if sum(Fraction(B[i][j]) * x[j] for j in range(r)) != Fraction(v[i]): return None
    return x

Fraction = F

def bar_homology(elems, mul, e, n):
    """H_n(G, Z) for a group given by its elements, multiplication and identity."""
    ne = [g for g in elems if g != e]
    def cells(k):
        out = [()]
        for _ in range(k): out = [c + (g,) for c in out for g in ne]
        return out
    def boundary(k):
        src, dst = cells(k), cells(k - 1)
        di = {c: i for i, c in enumerate(dst)}
        M = [[0] * len(src) for _ in range(len(dst))]
        for j, c in enumerate(src):
            terms = [(1, c[1:])]
            for i in range(k - 1):
                terms.append(((-1) ** (i + 1), c[:i] + (mul(c[i], c[i + 1]),) + c[i + 2:]))
            terms.append(((-1) ** k, c[:-1]))
            for sgn, t in terms:
                if e in t: continue                      # normalized: degenerate cells vanish
                M[di[t]][j] += sgn
        return M, len(src)
    Dn, nsrc = boundary(n)
    Dn1, n1src = boundary(n + 1)
    Kb = kernel_basis(Dn, nsrc)
    if not Kb: return []
    B = [[Kb[a][i] for a in range(len(Kb))] for i in range(nsrc)]
    coords = []
    for j in range(n1src):
        v = [Dn1[i][j] for i in range(nsrc)]
        x = solve_exact(B, v)
        if x is None or any(t.denominator != 1 for t in x): return None   # complex is wrong
        coords.append([int(t) for t in x])
    r = len(Kb)
    inv = smith_invariants([[coords[j][i] for j in range(n1src)] for i in range(r)], r, n1src)
    return ['Z'] * (r - len(inv)) + [f'Z/{d}' for d in inv if d != 1]

def as_group(perms):
    """Present a set of permutations as (elements, multiplication, identity) for the bar complex."""
    return sorted(perms), (lambda a, b: compose(a, b)), ID

# CONTROLS FIRST, and one of them must come back NONTRIVIAL. A multiplier routine that can only
# return the trivial group would certify anything, so Z/2 x Z/2 -- whose multiplier is Z/2 -- is
# run as a POSITIVE control alongside the vanishing ones. H_1 is checked too: it must reproduce the
# abelianization independently of anything this round wants to be true.
def cyc(n): return list(range(n)), (lambda a, b: (a + b) % n), 0
def prod22():
    els = [(a, b) for a in range(2) for b in range(2)]
    return els, (lambda x, y: ((x[0] + y[0]) % 2, (x[1] + y[1]) % 2)), (0, 0)

CONTROLS = [('Z/2', cyc(2), ['Z/2'], []), ('Z/3', cyc(3), ['Z/3'], []),
            ('Z/4', cyc(4), ['Z/4'], []), ('Z/2 x Z/2', prod22(), ['Z/2', 'Z/2'], ['Z/2'])]
CTRL_OK, CTRL_RESULT = True, {}
for name, (el, mu, idt), e1, e2 in CONTROLS:
    h1, h2 = bar_homology(el, mu, idt, 1), bar_homology(el, mu, idt, 2)
    CTRL_RESULT[name] = (h1, h2)
    CTRL_OK &= (h1 == e1 and h2 == e2)
POSITIVE_CONTROL_FIRES = (CTRL_RESULT['Z/2 x Z/2'][1] == ['Z/2'])

GEL, GMU, GID = as_group(GRP)
H1 = bar_homology(GEL, GMU, GID, 1)
H2 = bar_homology(GEL, GMU, GID, 2)
ok6 = CTRL_OK and POSITIVE_CONTROL_FIRES and (H2 == []) and (H1 == ['Z/2'])
check("NG6", ok6,
      f"the instrument group's integer homology, computed HERE from the normalized bar resolution "
      f"in exact integer arithmetic with Smith normal form — no library, no table, no cited value: "
      f"H_1 = {H1 or ['0']} and H_2 = {H2 or ['0']}. The machinery is controlled first and one "
      f"control is NONTRIVIAL by design: Z/2 x Z/2 returns H_2 = "
      f"{CTRL_RESULT['Z/2 x Z/2'][1]}, so a routine that could only ever answer 'trivial' is "
      f"excluded. Z/2, Z/3 and Z/4 return H_2 = 0 with H_1 the correct cyclic group, and H_1 here "
      f"independently reproduces the abelianization. SO THE SCHUR MULTIPLIER IS TRIVIAL, and since "
      f"U(1) is divisible and hence injective, H^2(-, U(1)) vanishes with it: every projective "
      f"representation of the genuine loop group is linearizable, and no choice of U_o gives a "
      f"gauge-invariant nontrivial class")

# ---------------------------------------------------------------- NG7  the construction boundary
# Depth one is not a setting. The kernel table is indexed by length-1 contexts, while the c = 1
# lookup a K >= 2 run performs asks for a length-2 context that has no entry. Demonstrated by
# running the construction at K = 2 and catching the failure, rather than argued from the source.
CTX_LENGTHS = {len(xs) for xs, _ in CTXS} | {len(as_) for _, as_ in CTXS}
K2_FAILS, K2_ERR = False, ''
try:
    _K = 2
    _XH = list(itertools.product(list(range(nV)) + [BLANK], repeat=_K))
    _AH = list(itertools.product(list(range(nA)) + [BLANK], repeat=_K))
    _S = [(x, h, a, u, c) for x in range(nV) for h in _XH for a in _AH
          for u in range(len(UTAB)) for c in range(_K + 1)]
    for s in _S:
        x, h, a, u, c = s
        if c < _K and wf_x(h, c) and wf_a(a, c, wrote=True):
            ctx = (tuple(list(h[:c]) + [x]), tuple(a[:c + 1]))
            _ = dict(UTAB[u])[ctx]
except KeyError as ex:
    K2_FAILS, K2_ERR = True, f'KeyError {ex}'
ok7 = K2_FAILS and (CTX_LENGTHS == {1})
